import React, { useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import styles from './Trainer.module.css';

const TrainerBottomNav = () => {
    const navigate = useNavigate();
    const location = useLocation();

    const tabs = [
        { id: 'home', icon: 'home', path: '/trainer/home' },
        { id: 'chat', icon: 'chat', path: '/trainer/chat' },
        { id: 'profile', icon: 'person', path: '/trainer/profile' }
    ];

    return (
        <div style={{
            position: 'fixed', bottom: 0, left: 0, width: '100%', height: '60px',
            backgroundColor: 'white', display: 'flex', justifyContent: 'space-around', alignItems: 'center',
            borderRadius: '30px 30px 0 0', boxShadow: '0 -2px 10px rgba(0, 0, 0, 0.05)', zIndex: 1000
        }}>
            {tabs.map(tab => {
                const isActive = location.pathname.startsWith(tab.path);
                return (
                    <div
                        key={tab.id}
                        style={{
                            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                            color: isActive ? 'var(--color-primary)' : 'var(--color-text-second)', cursor: 'pointer',
                            height: '100%', width: '60px', position: 'relative'
                        }}
                        onClick={() => navigate(tab.path)}
                    >
                        <span className="material-icons" style={{ fontSize: '28px' }}>{tab.icon}</span>
                        {isActive && <div style={{ position: 'absolute', top: 0, width: '30px', height: '3px', backgroundColor: 'var(--color-primary)', borderRadius: '0 0 3px 3px' }} />}
                    </div>
                );
            })}
        </div>
    );
};

export default TrainerBottomNav;

import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import dashboardData from '../../data/dashboardData';
import CachedImage from '../../components/CachedImage';
import styles from './Admin.module.css';

const AdminCategoryPage = () => {
  const navigate = useNavigate();
  const { categoryId } = useParams(); // 'food', 'supplements', 'clothes', 'exercises'

  // Map category to data
  const getCategoryData = () => {
    switch (categoryId) {
      case 'food': return { title: 'Food Store', items: dashboardData.foodItems };
      case 'supplements': return { title: 'Supplements', items: dashboardData.supplementItems };
      case 'clothes': return { title: 'Clothes', items: dashboardData.clothesItems };
      case 'exercises':
        // Flatten exercise categories for simple list view in admin
        const allEx = Object.values(dashboardData.exerciseItems).flat();
        return { title: 'Exercises', items: allEx };
      default: return { title: 'Store', items: [] };
    }
  };

  const { title, items } = getCategoryData();

  const [searchQuery, setSearchQuery] = useState('');

  const filteredItems = items.filter(item =>
    item.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleDelete = (e, id) => {
    e.stopPropagation();
    if (window.confirm('Delete this item?')) {
      // Mock delete
      alert('Item deleted (mock)');
    }
  };

  return (
    <div className={styles.pageContainer}>
      <div className={styles.appBar}>
        <div className={styles.headerRow} style={{ marginBottom: 0 }}>
          <button className={styles.backBtn} onClick={() => navigate(-1)}>
            <span className="material-icons">arrow_back_ios</span>
          </button>
          <span style={{ fontSize: '20px', fontWeight: 'bold' }}>Manage {title}</span>
        </div>
      </div>

      <div className={styles.scrollContent}>

        <div style={{ backgroundColor: 'white', borderRadius: '12px', padding: '12px 16px', display: 'flex', alignItems: 'center', marginBottom: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)', border: '1px solid #E0E0E0' }}>
          <span className="material-icons" style={{ color: 'var(--color-text-second)', marginRight: '8px' }}>search</span>
          <input
            type="text"
            placeholder={`Search ${title.toLowerCase()}...`}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ border: 'none', background: 'transparent', outline: 'none', width: '100%', fontSize: '16px' }}
          />
        </div>

        {filteredItems.length === 0 ? (
          <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--color-gray)' }}>No items found.</div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {filteredItems.map((item, idx) => (
              <div key={idx} className={styles.listItem} style={{ padding: '12px' }}>
                <CachedImage
                  imageUrl={item.image}
                  width="60px"
                  height="60px"
                  borderRadius={8}
                  fit="contain"
                />
                <div style={{ flex: 1, marginLeft: '16px' }}>
                  <div style={{ fontWeight: 'bold', fontSize: '16px' }}>{item.name}</div>
                  {(item.price || item.calories) && (
                    <div style={{ display: 'flex', gap: '16px', marginTop: '4px', fontSize: '12px' }}>
                      {item.price && <span style={{ color: 'var(--color-primary)', fontWeight: 'bold' }}>{item.price}</span>}
                      {item.calories && <span style={{ color: 'var(--color-calories)' }}>{item.calories}</span>}
                    </div>
                  )}
                  {item.description && (
                    <div style={{ color: 'var(--color-text-second)', fontSize: '12px', marginTop: '4px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '200px' }}>
                      {item.description}
                    </div>
                  )}
                </div>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button style={{ background: 'rgba(23,160,115,0.1)', color: 'var(--color-primary)', border: 'none', width: '36px', height: '36px', borderRadius: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                    <span className="material-icons" style={{ fontSize: '18px' }}>edit</span>
                  </button>
                  <button onClick={(e) => handleDelete(e, item.id)} style={{ background: 'rgba(255,0,0,0.1)', color: 'var(--color-error)', border: 'none', width: '36px', height: '36px', borderRadius: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                    <span className="material-icons" style={{ fontSize: '18px' }}>delete_outline</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <button className={styles.fab} onClick={() => navigate(`/admin/category/${categoryId}/add`)}>
        <span className="material-icons">add</span>
      </button>
    </div>
  );
};

export default AdminCategoryPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import useAuthStore from '../../stores/authStore';
import TextField from '../../components/TextField';
import Button from '../../components/Button';
import { Typography, showToast } from '../../utils/custom';
import Logo from '../../assets/images/nav.png';
import styles from './Auth.module.css';

const LoginPage = () => {
  const navigate = useNavigate();
  const { login, isLoading, error } = useAuthStore();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      showToast('Please fill in all fields', true);
      return;
    }

    const success = await login(email, password);
    if (success) {
      const { user } = useAuthStore.getState();
      if (user?.role === 'Trainee') navigate('/trainee/home', { replace: true });
      else if (user?.role === 'Trainer') navigate('/trainer/home', { replace: true });
      else if (user?.role === 'Admin') navigate('/admin/home', { replace: true });
      else navigate('/trainee/home', { replace: true });
    } else {
      showToast(useAuthStore.getState().error || 'Login failed', true);
    }
  };

  return (
    <div className={styles.pageContainer}>
      <div className={styles.scrollContent}>
        <img src={Logo} alt="Power Pulse" className={styles.navLogo} />

        <div className={styles.headerArea}>
          {Typography.mainText('Sign in')}
          <p className={styles.subtitle}>
            If you don't have an account register<br />
            You can{' '}
            <Link to="/register" className={styles.linkText}>Register here !</Link>
          </p>
        </div>

        <form onSubmit={handleLogin} className={styles.formArea}>
          <TextField
            label="Email"
            placeholder="Enter your email address"
            icon="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />

          <div className={styles.spacer}></div>

          <TextField
            label="Password"
            placeholder="Enter your Password"
            type="password"
            icon="lock_outline"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />

          <div className={styles.optionsRow}>
            <label className={styles.checkboxLabel}>
              <input
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
              />
              <span>Remember me</span>
            </label>
            <Link to="/forgot-password" className={styles.linkTextSmall}>
              Forgot Password
            </Link>
          </div>

          <div className={styles.submitArea}>
            <Button
              onClick={handleLogin}
              disabled={isLoading}
              className={styles.loginBtn}
            >
              {isLoading ? 'Loading...' : 'Login'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import useAuthStore from '../../stores/authStore';
import useTraineeStore from '../../stores/traineeStore';
import CachedImage from '../../components/CachedImage';
import styles from './Trainee.module.css';

const OrdersPage = () => {
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const { orders, fetchOrders, isLoading } = useTraineeStore();

  useEffect(() => {
    if (user?.id) {
      fetchOrders(user.id);
    }
  }, [user?.id, fetchOrders]);

  return (
    <div className={styles.pageContainer}>
      <div className={styles.appBar}>
        <div className={styles.headerRow} style={{ marginBottom: 0 }}>
          <button className={styles.backBtn} onClick={() => navigate(-1)}>
            <span className="material-icons">arrow_back_ios</span>
          </button>
          <span style={{ fontSize: '20px', fontWeight: 'bold' }}>My Orders</span>
        </div>
      </div>

      <div className={styles.scrollContent}>
        {isLoading ? (
          <div style={{ textAlign: 'center', marginTop: '40px' }}>Loading orders...</div>
        ) : orders.length === 0 ? (
          <div style={{ textAlign: 'center', color: 'var(--color-text-second)', marginTop: '40px' }}>
            You haven't placed any orders yet.
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {orders.map((order, idx) => (
               <div key={order.id || idx} style={{ backgroundColor: 'var(--color-white)', borderRadius: '16px', padding: '16px', border: '1px solid #F0F0F0', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
                 <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '12px' }}>
                   <span style={{ fontWeight: 'bold' }}>Order #{order.id?.substring(0,8) || 'XXXX'}</span>
                   <span style={{ color: order.status === 'Delivered' ? 'var(--color-save)' : 'var(--color-primary)', fontWeight: 'bold', fontSize: '14px' }}>
                     {order.status || 'Processing'}
                   </span>
                 </div>
                 <div style={{ fontSize: '12px', color: 'var(--color-text-second)', marginBottom: '16px' }}>
                   {new Date(order.createdAt).toLocaleDateString()}
                 </div>

                 {/* Order Items Summary */}
                 <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '16px' }}>
                   {order.items?.map((item, itemIdx) => (
                     <div key={itemIdx} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                       <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                         <div style={{ width: '30px', height: '30px', backgroundColor: '#F5F5F5', borderRadius: '4px', display: 'flex', alignItems: 'center', justify-content: 'center' }}>
                           <CachedImage imageUrl={item.image} width="100%" height="100%" fit="contain" />
                         </div>
                         <span style={{ fontSize: '14px' }}>{item.title}</span>
                       </div>
                       <span style={{ fontSize: '14px', fontWeight: 'bold' }}>x{item.quantity}</span>
                     </div>
                   ))}
                 </div>

                 <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid #F0F0F0', paddingTop: '12px' }}>
                   <span style={{ color: 'var(--color-text-second)' }}>Total Amount</span>
                   <span style={{ fontWeight: 'bold', color: 'var(--color-primary)' }}>{order.totalAmount} EGP</span>
                 </div>
               </div>
        ))}
      </div>
        )}
    </div>
    </div >
  );
};

export default OrdersPage;

