import apiClient from './apiClient';

export const chatService = {
    getContacts: async (userId, role) => {
        const response = await apiClient.get('/api/chat/contacts', {
            params: { userId, role }
        });
        return response.data;
    },

    markChatAsRead: async (targetId) => {
        const response = await apiClient.put(`/api/Chat/${targetId}/read`);
        return response.data;
    },

    sendMessage: async (messageData) => {
        const response = await apiClient.post('/api/chat', messageData);
        return response.data;
    },

    getMessages: async (user1Id, user2Id, user1Role, user2Role) => {
        const response = await apiClient.get('/api/chat', {
            params: { userId1: user1Id, userId2: user2Id }
        });
        return response.data;
    }
};

import apiClient from './apiClient';

export const trainerService = {
    getTrainers: async () => {
        const response = await apiClient.get('/api/trainers');
        return response.data;
    },

    getTrainerDetails: async (id) => {
        const response = await apiClient.get(`/api/trainers/${id}`);
        return response.data;
    },

    getTrainerStats: async (id) => {
        try {
            const response = await apiClient.get(`/api/trainers/${id}/stats`);
            return response.data;
        } catch (e) {
            return { totalClients: 0, todayAmount: 0.0, totalAmount: 0.0 };
        }
    },

    getTrainerSubscriptions: async (trainerId) => {
        const response = await apiClient.get(`/api/subscriptions/trainer/${trainerId}`);
        return response.data;
    },

    getPlans: async (trainerId) => {
        const response = await apiClient.get(`/api/trainers/${trainerId}/plans`);
        return response.data;
    },

    createPlan: async (trainerId, planData) => {
        const response = await apiClient.post(`/api/trainers/${trainerId}/plans`, planData);
        return response.data;
    },

    updatePlan: async (trainerId, planId, planData) => {
        const response = await apiClient.put(`/api/trainers/${trainerId}/plans/${planId}`, planData);
        return response.data;
    },

    deletePlan: async (trainerId, planId) => {
        const response = await apiClient.delete(`/api/trainers/${trainerId}/plans/${planId}`);
        return response.data;
    },

    addWorkout: async (trainerId, workoutData) => {
        const response = await apiClient.post(`/api/trainers/${trainerId}/workouts`, workoutData);
        return response.data;
    },

    updateProfile: async (trainerId, data) => {
        const response = await apiClient.put(`/api/trainers/${trainerId}`, data);
        return response.data;
    },

    updateProfileImage: async (trainerId, imageUrl) => {
        const response = await apiClient.put(`/api/trainers/${trainerId}`, { profileImageUrl: imageUrl });
        return response.data;
    },

    addDailyNote: async (subscriptionId, title, noteText) => {
        const data = { noteText };
        if (title && title.trim() !== '') {
            data.title = title;
        }
        const response = await apiClient.post(`/api/subscriptions/${subscriptionId}/notes`, data);
        return response.data;
    },

    getSubscriptionDetails: async (subscriptionId) => {
        const response = await apiClient.get(`/api/subscriptions/${subscriptionId}`);
        return response.data;
    },

    addCertificate: async (trainerId, certificateData) => {
        const response = await apiClient.post(`/api/trainers/${trainerId}/certificates`, certificateData);
        return response.data;
    },

    deleteCertificate: async (trainerId, certId) => {
        const response = await apiClient.delete(`/api/trainers/${trainerId}/certificates/${certId}`);
        return response.data;
    }
};

import { create } from 'zustand';
import { chatService } from '../services/chatService';
import * as signalR from '@microsoft/signalr';

const useChatStore = create((set, get) => ({
    contacts: [],
    messages: [],
    isLoading: false,
    error: null,

    hubConnection: null,
    currentUserId: null,
    currentUserRole: null,
    activeChatPartnerId: null,
    pollingTimer: null,
    isReconnecting: false,

    connectSignalR: async (userId, role) => {
        const { hubConnection, currentUserId, currentUserRole } = get();

        set({ currentUserId: userId, currentUserRole: role });

        if (hubConnection && hubConnection.state === signalR.HubConnectionState.Connected) {
            return;
        }

        if (hubConnection) {
            try {
                await hubConnection.stop();
            } catch (e) {
                // ignore
            }
        }

        const newConnection = new signalR.HubConnectionBuilder()
            .withUrl("http://powerpuls.runasp.net/chathub")
            .withAutomaticReconnect()
            .build();

        newConnection.on("ReceiveMessage", (message) => {
            const state = get();
            if (!message || typeof message !== 'object') return;

            const { activeChatPartnerId, currentUserId, currentUserRole } = state;
            const mapMsg = message instanceof Array ? message[0] : message;

            if (activeChatPartnerId !== null) {
                const senderId = mapMsg.senderId;
                const receiverId = mapMsg.receiverId;
                const belongsToChat = senderId === activeChatPartnerId || receiverId === activeChatPartnerId;

                if (belongsToChat) {
                    const exists = state.messages.some(m => m.id === mapMsg.id && mapMsg.id != null);
                    if (!exists) {
                        set({ messages: [mapMsg, ...state.messages] });
                    }
                }
            }

            // refresh contacts
            if (currentUserId && currentUserRole) {
                get().fetchContacts(currentUserId, currentUserRole, false);
            }
        });

        newConnection.onclose((error) => {
            console.log("SignalR disconnected:", error);
            get().attemptReconnect();
        });

        newConnection.onreconnecting((error) => {
            console.log("SignalR reconnecting:", error);
        });

        newConnection.onreconnected((connectionId) => {
            console.log("SignalR reconnected with id:", connectionId);
            const state = get();
            if (state.currentUserId && state.currentUserRole) {
                state.hubConnection.invoke("JoinUserGroup", state.currentUserId.toString(), state.currentUserRole).catch(e => {
                    console.error("Failed to re-join group:", e);
                });
            }
        });

        try {
            await newConnection.start();
            await newConnection.invoke("JoinUserGroup", userId.toString(), role);
            set({ hubConnection: newConnection });
            console.log("Successfully connected to SignalR");
        } catch (e) {
            console.error("SignalR connection error:", e);
            get().attemptReconnect();
        }
    },

    attemptReconnect: () => {
        const state = get();
        if (state.isReconnecting) return;
        set({ isReconnecting: true });

        setTimeout(async () => {
            set({ isReconnecting: false });
            const current = get();
            if (current.currentUserId && current.currentUserRole) {
                if (!current.hubConnection || current.hubConnection.state !== signalR.HubConnectionState.Connected) {
                    console.log("Attempting reconnect...");
                    set({ hubConnection: null });
                    await get().connectSignalR(current.currentUserId, current.currentUserRole);
                }
            }
        }, 3000);
    },

    disconnectSignalR: () => {
        const { hubConnection } = get();
        if (hubConnection) {
            hubConnection.stop();
            set({ hubConnection: null });
        }
    },

    startPolling: (myUserId, partnerId, myRole) => {
        const { pollingTimer } = get();
        if (pollingTimer) clearInterval(pollingTimer);

        set({ activeChatPartnerId: partnerId });

        const newTimer = setInterval(async () => {
            try {
                const fetchedMessages = await chatService.getMessages(myUserId, partnerId, myRole);
                const newMessages = fetchedMessages.reverse();

                const state = get();
                const currentLatestId = state.messages.length > 0 ? state.messages[0].id : null;
                const fetchedLatestId = newMessages.length > 0 ? newMessages[0].id : null;

                if (currentLatestId !== fetchedLatestId || state.messages.length !== newMessages.length) {
                    set({ messages: newMessages });
                }
            } catch (e) {
                console.error("Polling error:", e);
            }
        }, 5000);

        set({ pollingTimer: newTimer });
    },

    stopPolling: () => {
        const { pollingTimer } = get();
        if (pollingTimer) {
            clearInterval(pollingTimer);
        }
        set({ pollingTimer: null, activeChatPartnerId: null });
    },

    fetchContacts: async (userId, role, showLoading = true) => {
        get().connectSignalR(userId.toString(), role);
        if (showLoading) set({ isLoading: true, error: null });

        try {
            const contacts = await chatService.getContacts(userId, role);
            set({ contacts, ...(showLoading && { isLoading: false }) });
        } catch (error) {
            set({ error: error.message, ...(showLoading && { isLoading: false }) });
        }
    },

    markChatAsRead: async (targetId) => {
        try {
            await chatService.markChatAsRead(targetId);
            const { contacts } = get();
            const updatedContacts = contacts.map(c =>
                c.userId === targetId ? { ...c, unreadCount: 0 } : c
            );
            set({ contacts: updatedContacts });
        } catch (error) {
            console.error("Failed to mark chat as read:", error);
        }
    },

    fetchMessages: async (user1Id, user2Id, user1Role, user2Role) => {
        get().connectSignalR(user1Id.toString(), user1Role || '');
        set({ activeChatPartnerId: user2Id, isLoading: true, error: null });

        try {
            const fetchedMessages = await chatService.getMessages(user1Id, user2Id, user1Role, user2Role);
            set({ messages: fetchedMessages.reverse(), isLoading: false });
        } catch (error) {
            set({ error: error.message, isLoading: false });
        }
    },

    sendMessage: async (data) => {
        set({ error: null });
        try {
            const newMessage = await chatService.sendMessage(data);
            set(state => ({ messages: [newMessage, ...state.messages] }));
            return true;
        } catch (error) {
            const msg = error.response?.data?.message || error.response?.data?.error || error.message;
            set({ error: msg });
            return false;
        }
    },

    clearError: () => set({ error: null })
}));

export default useChatStore;

import { create } from 'zustand';
import { traineeService } from '../services/traineeService';

const useTraineeStore = create((set, get) => ({
    trainee: null,
    trainerWorkouts: [],
    orders: [],
    addresses: [],
    isLoading: false,
    error: null,

    fetchProfile: async (id) => {
        set({ isLoading: true, error: null });
        try {
            const data = await traineeService.getProfile(id);
            set({ trainee: data, isLoading: false });
        } catch (error) {
            set({ error: error.message, isLoading: false });
        }
    },

    fetchAddresses: async (traineeId) => {
        set({ isLoading: true, error: null });
        try {
            const addresses = await traineeService.getAddresses(traineeId);
            set({ addresses, isLoading: false });
        } catch (error) {
            set({ error: error.message, isLoading: false });
        }
    },

    fetchTrainerWorkouts: async (traineeId) => {
        set({ isLoading: true, error: null });
        try {
            const workouts = await traineeService.getTrainerWorkouts(traineeId);
            set({ trainerWorkouts: workouts, isLoading: false });
        } catch (error) {
            set({ error: error.message, isLoading: false });
        }
    },

    fetchOrders: async (traineeId) => {
        set({ isLoading: true, error: null });
        try {
            const orders = await traineeService.getTraineeOrders(traineeId);
            set({ orders: orders.sort((a, b) => b.id - a.id), isLoading: false });
        } catch (error) {
            set({ error: error.message, isLoading: false });
        }
    },

    placeOrder: async (orderData) => {
        set({ isLoading: true, error: null });
        try {
            const order = await traineeService.placeOrder(orderData);
            set(state => ({ orders: [order, ...state.orders], isLoading: false }));
            return order;
        } catch (error) {
            set({ error: error.message, isLoading: false });
            return null;
        }
    }
}));

export default useTraineeStore;
